import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    // 2026-10-31 02:00 in Warsaw (CET, UTC+1): the nightly run time.
    private static final Instant NOW = Instant.parse("2026-10-31T01:00:00Z");
    private static final long DAY = 86_400L;

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, Clock.fixed(NOW, ZoneOffset.UTC));

    private Order place(String id, Instant placedAt, String status) {
        Order order = new Order(id, "c-1", Money.pln(1000), placedAt);
        order.changeStatus(status);
        orders.save(order);
        return order;
    }

    @Test
    void cancelsOnlyPlacedOrdersMoreThanThirtyDaysOld() {
        Order old = place("old", NOW.minusSeconds(40 * DAY), "PLACED");
        Order thirtyOneDays = place("31-days", NOW.minusSeconds(31 * DAY), "PLACED");
        Order thirtyDays = place("30-days", NOW.minusSeconds(30 * DAY), "PLACED");
        Order recent = place("recent", NOW.minusSeconds(29 * DAY), "PLACED");
        Order oldConfirmed = place("old-confirmed", NOW.minusSeconds(60 * DAY), "CONFIRMED");

        int cancelled = service.expireStale();

        assertEquals(2, cancelled);
        assertEquals("CANCELLED", old.status());
        assertEquals("CANCELLED", thirtyOneDays.status());
        assertEquals("PLACED", thirtyDays.status());
        assertEquals("PLACED", recent.status());
        assertEquals("CONFIRMED", oldConfirmed.status());
    }

    @Test
    void daysAreCountedInWarsawNotUtc() {
        // Warsaw midnight between 30 Sep and 1 Oct is 22:00 UTC on 30 Sep.
        // 1 Oct is the oldest date kept, so 30 Sep is expired.
        Order lastSecondOfSept30 = place("sep30", Instant.parse("2026-09-30T21:59:59Z"), "PLACED");
        Order firstSecondOfOct1 = place("oct1", Instant.parse("2026-09-30T22:00:00Z"), "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", lastSecondOfSept30.status());
        assertEquals("PLACED", firstSecondOfOct1.status());
    }

    @Test
    void secondRunCancelsNothing() {
        place("old", NOW.minusSeconds(40 * DAY), "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
